private void setupTestDeprecated() throws ParseException {
    handler = new HashSet<>();
    parser = DefaultParser.builder()
            .setDeprecatedHandler(handler::add)
            .build();

    opt1 = Option.builder()
            .option("d1")
            .deprecated()
            .build();

    // @formatter:off
    opt2 = Option.builder()
            .option("d2")
            .deprecated(DeprecatedAttributes.builder()
                    .setForRemoval(true)
                    .setSince("1.0")
                    .setDescription("Do this instead.")
                    .get())
            .build();
    // @formatter:on

    opt3 = Option.builder()
            .option("a")
            .build();

    // @formatter:off
    cl = parser.parse(new Options()
            .addOption(opt1)
            .addOption(opt2)
            .addOption(opt3),
            new String[] {"-d1", "-d2", "-a"});
    // @formatter:on
}

@Test
public void testDeprecated_OptionPresence() throws ParseException {
    setupTestDeprecated();

    assertTrue(cl.hasOption(opt1.getOpt()),
            "Parser should report option 'd1' as present");
    assertTrue(cl.hasOption(opt2.getOpt()),
            "Parser should report option 'd2' as present");
    assertTrue(cl.hasOption(opt3.getOpt()),
            "Parser should report option 'a' as present");
