    int indexOfInt = list.indexOf(1); // should only contain JsonPrimitive(1)
    assertThat(indexOfInt)
        .named("indexOf(1) with raw int should return -1 because list holds JsonPrimitives")
        .isEqualTo(-1);

    assertThat(list.lastIndexOf(new JsonPrimitive(1)))
        .named("lastIndexOf(JsonPrimitive(1)) should return the last occurrence index 1")
        .isEqualTo(1);
    assertThat(list.lastIndexOf(new JsonPrimitive(2)))
        .named("lastIndexOf(JsonPrimitive(2)) should return -1 when element is absent")
        .isEqualTo(-1);
    assertThat(list.lastIndexOf(null))
        .named("lastIndexOf(null) should return -1 when searching for null")
        .isEqualTo(-1);
}

