/**
 * Helper method to obtain the {@link AssertionError} thrown when trying to instantiate an
 * abstract class via {@link UnsafeAllocator}. This method does not contain any test assertions.
 */
private static AssertionError instantiateAbstractClass() {
  try {
    UnsafeAllocator.INSTANCE.newInstance(AbstractClass.class);
    throw new IllegalStateException("Expected AssertionError was not thrown");
  } catch (AssertionError error) {
    return error;
  }
}

