    JsonWriter jsonWriter = new JsonWriter(stringWriter);
    jsonWriter.setStrictness(Strictness.LENIENT);
    jsonWriter.setFormattingStyle(style);
    jsonWriter.beginArray();
    for (double v : values) {
        jsonWriter.value(v);
    }
    jsonWriter.endArray();
    return stringWriter.toString();
}

