    assertEquals("HTML output should preserve SYSTEM DOCTYPE declaration", systemDoc, htmlOutput(systemDoc));
    assertEquals("XML output should preserve SYSTEM DOCTYPE declaration", systemDoc, xmlOutput(systemDoc));

