// Helper to create an Element with a given class attribute value
private Element createElement(String classAttribute) {
    Tag tag = Tag.valueOf("a");
    Attributes attribs = new Attributes();
    Element el = new Element(tag, "", attribs);
    attribs.put("class", classAttribute);
    return el;
}

@ParameterizedTest(name = "Positive: class attribute \"{0}\" should contain \"{1}\"")
@CsvSource({
    "'toto',                'toto'",
    "' toto',               'toto'",
    "'toto ',               'toto'",
    "'\ttoto ',             'toto'",
    "'  toto ',             'toto'",
    "'raulpismuth  ',       'raulpismuth'",
    "' abcd  raulpismuth efgh ', 'raulpismuth'",
    "' abcd efgh raulpismuth',     'raulpismuth'",
    "' abcd efgh raulpismuth ',    'raulpismuth'"
})
void testHasClass_PositiveWhitespaceHandling(String classAttr, String queryClass) {
    Element el = createElement(classAttr);
    boolean hasClass = el.hasClass(queryClass);
    assertTrue(hasClass,
        String.format("Class attribute \"%s\" should be recognised as containing \"%s\".", classAttr, queryClass));
}

@ParameterizedTest(name = "Negative: class attribute \"{0}\" should NOT contain \"{1}\"")
@CsvSource({
    "'ab',    'toto'",
    "'     ', 'toto'",
    "'tototo','toto'"
})
void testHasClass_NegativeCases(String classAttr, String queryClass) {
    Element el = createElement(classAttr);
    boolean hasClass = el.hasClass(queryClass);
    assertFalse(hasClass,
        String.format("Class attribute \"%s\" should NOT be recognised as containing \"%s\".", classAttr, queryClass));
}

