// Helper method to set up the document, original element, and its clone
private Element[] initCloneTestElements() {
    Document doc = Jsoup.parse("<div class=foo>Text</div>");
    Element el = doc.select("div").first();
    Element elClone = doc.clone().select("div").first();
    return new Element[]{el, elClone};
}

@Test
public void supportsClone_initialState() {
    Element[] elems = initCloneTestElements();
    Element el = elems[0];
    Element elClone = elems[1];

    assertTrue("Original element should have class 'foo'", el.hasClass("foo"));
    assertTrue("Cloned element should have class 'foo'", elClone.hasClass("foo"));
    assertEquals("Cloned element should retain text 'Text'", "Text", elClone.text());
}

@Test
public void supportsClone_unaffectedAfterOriginalModification() {
    Element[] elems = initCloneTestElements();
    Element el = elems[0];
    Element elClone = elems[1];

    // Modify the original element
    el.removeClass("foo");
    el.text("None");

    assertFalse("Original element should no longer have class 'foo'", el.hasClass("foo"));
    assertTrue("Cloned element should still have class 'foo'", elClone.hasClass("foo"));
    assertEquals("Original element text should be changed to 'None'", "None", el.text());
    assertEquals("Cloned element text should remain 'Text'", "Text", elClone.text());
}

