@Test
public void testNewsHomepage(@TempDir Path tempDir) throws IOException {
    // Copy the HTML fixture into the temporary directory
    Path target = tempDir.resolve("news-com-au-home.html");
    try (InputStream resource = ParseTest.class.getResourceAsStream("/htmltests/news-com-au-home.html")) {
        Files.copy(resource, target, StandardCopyOption.REPLACE_EXISTING);
    }

    File in = target.toFile();

    // Ensure the fixture file exists before parsing
    assertTrue(in.exists(), "Input file 'news-com-au-home.html' must exist before parsing");

    Document doc = Jsoup.parse(in, "UTF-8", "http://www.news.com.au/");
    assertEquals("News.com.au | News from Australia and around the world online | NewsComAu",
                 doc.title(),
                 "Document title should match the expected site title");
    assertEquals("Brace yourself for Metro meltdown",
                 doc.select(".id1225817868581 h4").text().trim(),
                 "Header text should be the expected tagline");

    Element a = doc.select("a[href=/entertainment/horoscopes]").first();
    assertEquals("/entertainment/horoscopes",
                 a.attr("href"),
                 "Link href should be the relative path defined in the fixture");
    assertEquals("http://www.news.com.au/entertainment/horoscopes",
                 a.attr("abs:href"),
                 "Link absolute href should be correctly resolved");

    Element hs = doc.select("a[href*=naughty-corners-are-a-bad-idea]").first();
    assertEquals("http://www.heraldsun.com.au/news/naughty-corners-are-a-bad-idea-for-kids/story-e6frf7jo-1225817899003",
                 hs.attr("href"),
                 "External link href should match the expected URL");
    assertEquals(hs.attr("href"),
                 hs.attr("abs:href"),
                 "External link absolute href should equal its href attribute");
}

