private static final String HTML = "<div>One <p>Two <p>Three";

private static Document parseDocument() {
    return Jsoup.parse(HTML);
}

private static List<TextNode> getAllTextNodes(Document doc) {
    List<TextNode> textNodes = new ArrayList<>();
    for (Element el : doc.getAllElements()) {
        for (Node node : el.childNodes()) {
            if (node instanceof TextNode) {
                textNodes.add((TextNode) node);
            }
        }
    }
    return textNodes;
}

private static TextNode getFirstTextNode(Document doc) {
    for (Element el : doc.getAllElements()) {
        for (Node node : el.childNodes()) {
            if (node instanceof TextNode) {
                return (TextNode) node;
            }
        }
    }
    return null;
}

private static void assertAllTextNodesNonBlank(List<TextNode> nodes) {
    for (TextNode tn : nodes) {
        assertFalse(StringUtil.isBlank(tn.text()));
    }
}

private static void assertFirstTextNodeValues(TextNode textNode) {
    assertEquals("One ", textNode.text());
    assertEquals("One ", textNode.getWholeText());
}

static boolean hasFirstTextNode() {
    Document doc = parseDocument();
    return getFirstTextNode(doc) != null;
}

@Test
void testHasTextWhenIterating_NonBlankTextNodeCheck() {
